const jsonHeaders = { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" };
function clean(value: unknown): string { return typeof value === "string" ? value.trim() : ""; }
function sleep(ms: number) { return new Promise((resolve) => setTimeout(resolve, ms)); }
function norm(value: string) { return value.trim().toLowerCase(); }
async function getGraphToken(env: Env): Promise<string> {
  const tenantId = clean(env.M365_TENANT_ID); const clientId = clean(env.M365_CLIENT_ID); const clientSecret = clean(env.M365_CLIENT_SECRET);
  if (!tenantId || !clientId || !clientSecret) throw new Error("Microsoft Graph credentials are not configured.");
  const now = Date.now(); if (graphTokenCache && graphTokenCache.expiresAt > now + 60000) return graphTokenCache.token;
  const body = new URLSearchParams({ client_id: clientId, client_secret: clientSecret, scope: "https://graph.microsoft.com/.default", grant_type: "client_credentials" });
  const response = await fetch(`https://login.microsoftonline.com/${encodeURIComponent(tenantId)}/oauth2/v2.0/token`, { method: "POST", headers: { "content-type": "application/x-www-form-urlencoded" }, body });
  const payload = await response.json<Record<string, any>>().catch(() => ({}));
  if (!response.ok || !payload.access_token) throw new Error(payload.error_description || payload.error || `Graph token failed ${response.status}`);
  graphTokenCache = { token: payload.access_token, expiresAt: now + Number(payload.expires_in || 3300) * 1000 }; return graphTokenCache.token;
}
async function graph(env: Env, path: string, init: RequestInit = {}) {
  const sender = clean(env.M365_SENDER); if (!sender) throw new Error("M365 sender is not configured.");
  const token = await getGraphToken(env);
  const response = await fetch(`https://graph.microsoft.com/v1.0/users/${encodeURIComponent(sender)}${path}`, { ...init, headers: { authorization: `Bearer ${token}`, accept: "application/json", ...(init.headers || {}) } });
  const text = await response.text(); let body: any = null; if (text) { try { body = JSON.parse(text); } catch { body = text; } }
  if (!response.ok) throw new Error(typeof body === "string" ? body : (body?.error?.message || `Graph ${response.status} for ${path}`));
  return { status: response.status, body };
}
async function listSent(env: Env) {
  const res = await graph(env, `/mailFolders/sentitems/messages?$top=100&$select=id,subject,toRecipients,sentDateTime&$orderby=sentDateTime desc`);
  return (res.body?.value || []) as any[];
}
function msgToAddresses(msg: any): string[] { return (msg.toRecipients || []).map((r: any) => norm(r?.emailAddress?.address || "")).filter(Boolean); }
function matches(msg: any, expected: any) { return msg.subject === expected.subject && msgToAddresses(msg).includes(norm(expected.to)); }
async function verify(env: Env) {
  const sent = await listSent(env);
  return EMAILS.map((expected: any) => { const hit = sent.find((m) => matches(m, expected)); return { customer: expected.customer, to: expected.to, subject: expected.subject, sentFound: Boolean(hit), sentAt: hit?.sentDateTime || null }; });
}
async function sendOne(env: Env, item: any) {
  const message = {
    subject: item.subject,
    body: { contentType: "HTML", content: item.html },
    toRecipients: [{ emailAddress: { address: item.to } }],
    attachments: [{ "@odata.type": "#microsoft.graph.fileAttachment", name: item.attachmentName, contentType: "image/png", contentBytes: item.attachmentBytes }]
  };
  await graph(env, `/sendMail`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ message, saveToSentItems: true }) });
}
export const onRequestPost: PagesFunction<Env> = async (context) => {
  try {
    const payload = await context.request.json<any>().catch(() => ({}));
    if (payload.key !== APPROVAL_KEY) return new Response(JSON.stringify({ ok: false, error: "unauthorized" }), { status: 401, headers: jsonHeaders });
    if (payload.action === "verify") return new Response(JSON.stringify({ ok: true, verification: await verify(context.env) }, null, 2), { headers: jsonHeaders });
    const sentBefore = await listSent(context.env); const results: any[] = [];
    for (const item of EMAILS) {
      if (sentBefore.some((m) => matches(m, item))) { results.push({ customer: item.customer, to: item.to, subject: item.subject, status: "already-sent-before-this-run" }); continue; }
      await sendOne(context.env, item); results.push({ customer: item.customer, to: item.to, subject: item.subject, attachment: item.attachmentName, status: "send-called" }); await sleep(500);
    }
    let verification = await verify(context.env);
    for (let i=0; i<5 && verification.some((v: any) => !v.sentFound); i++) { await sleep(1500); verification = await verify(context.env); }
    return new Response(JSON.stringify({ ok: true, results, verification }, null, 2), { headers: jsonHeaders });
  } catch (error: any) { return new Response(JSON.stringify({ ok: false, error: error?.message || String(error) }, null, 2), { status: 500, headers: jsonHeaders }); }
};
export const onRequestGet: PagesFunction<Env> = async () => new Response(JSON.stringify({ ok: false, error: "POST required" }), { status: 405, headers: jsonHeaders });
